{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 쿼리에 인덱스를 추가한 판단이 실행 계획에서 확인한 구체적인 병목 단서에 기반했는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 운영 화면의 신고 목록 조회 쿼리가 느렸던 상황",
          "task": "실행 계획에서 인덱스 추가가 필요한 근거를 찾는 일",
          "action": "실제로 확인한 실행 계획의 단서를 신고 목록 조회 조건과 연결해 설명",
