          ]
        },
        "acceptable": {
          "criteria": [
            "신고 목록 조회 쿼리에 인덱스가 필요했던 이유를 전체 스캔이나 검색 효율 같은 일반적인 설명으로 제시하지만, 실제 실행 계획에서 확인한 단서는 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "신고 목록 조회 쿼리의 실행 계획에서 확인한 단서 없이 인덱스를 추가했다는 사실이나 응답 시간 단축 성과만 반복한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "배포 후 발생한 API 오류의 원인 추적을 시작할 구체적인 로그 항목을 선택할 수 있는지 확인한다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "서버 배포 직후 판매글 신고 접수 API에서 오류가 늘어난 상황",
          "task": "오류 원인 추적의 출발점이 될 로그 항목을 선택하는 일",
          "action": "오류 요청에서 우선 확인할 로그 항목을 구체적으로 지목",
          "result": "선택한 로그 항목에서 오류 발생 위치나 공통된 예외를 확인할 것으로 예상"
        },
        "expectedEvidence": [
          "원인 추적을 시작할 구체적인 로그 항목",
          "선택한 로그 항목에서 확인하려는 오류의 세부 정보"
        ]
      },
      "question": "서버 배포 직후 판매글 신고 접수 API에서 오류가 늘었다면, 원인 추적의 출발점으로 삼을 로그 항목은 무엇인가요?",
      "answerTip": "가정한 상황에서 본인이 먼저 살펴볼 대상을 떠올려 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "판매글 신고 접수 API의 오류 로그에서 예외 메시지나 스택 추적 등 확인할 항목을 구체적으로 지목하고, 그 항목에서 찾을 오류 정보를 명확히 말한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "판매글 신고 접수 API의 서버 로그나 오류 로그를 보겠다고 답하지만, 그 안에서 확인할 항목은 구체적으로 지목하지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "판매글 신고 접수 API의 원인 추적에 사용할 로그 항목을 제시하지 않거나, 재배포 같은 복구 조치만 이야기한다."
          ]
        }
      }
    }
  ]
}

