{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "진통제 처방의 용량을 의심해 투약을 멈추고 확인해야 한다고 판단한 근거가 구체적인지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 들어온 상황",
          "task": "투약 전에 처방 용량의 적절성을 확인해야 하는 상황",
          "action": "당시 비교한 용량 정보와 새 처방에서 발견한 차이를 중심으로 판단 근거를 설명",
          "result": "발견한 차이가 투약 전 확인이 필요한 근거였음을 정리"
        },
        "expectedEvidence": [
          "처방 용량을 그대로 투약하기 어렵다고 판단한 구체적인 근거",
          "당시 평소 용량의 기준으로 삼았던 정보",
          "그 정보와 실제 처방 용량 사이에서 확인한 차이"
        ]
      },
      "question": "진통제 처방 용량이 평소의 두 배로 들어왔던 일에서, 투약 전 확인이 필요하다고 판단한 구체적인 근거는 무엇이었나요?",
      "answerTip": "당시 직접 확인한 사실을 중심으로 짧게 설명해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "진통제 처방을 의심한 근거로 당시 비교한 용량 정보의 출처나 구체적인 내용을 제시하고, 새 처방과의 차이를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "진통제 처방이 평소 용량의 두 배여서 의심했다고 말하지만, 비교 기준으로 삼은 용량 정보는 구체적으로 설명하지 못한다."
          ]
        },
        "poor": {
          "criteria": [
            "진통제 처방을 의심한 근거를 제시하지 않거나, 담당의에게 확인했다는 후속 행동만 설명한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환자 상태 관찰 기록에서 이전 상태와의 변화를 드러내는 구체적인 관찰 정보를 남겼는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동에서 활력징후와 통증을 관찰하고 간호 기록을 작성하던 업무",
          "task": "환자 상태의 변화를 알 수 있는 관찰 정보를 기록에 남기는 일",
          "action": "실제 기록에 포함했던 관찰 정보를 구체적인 항목이나 표현으로 설명",
          "result": "제시한 기록 정보에서 환자 상태의 어떤 변화를 읽을 수 있는지 정리"
        },
        "expectedEvidence": [
          "환자 상태의 변화를 드러내기 위해 실제로 기록한 관찰 정보",
          "활력징후 수치나 통증 척도 등 관찰 정보를 표현한 구체적인 형태",
          "관찰 시각이나 이전 관찰값 등 변화 비교에 필요한 기록 내용"
        ]
      },
      "question": "정형외과 병동에서 활력징후와 통증을 관찰해 기록하셨는데, 환자 상태의 변화를 드러내는 데 빠뜨리지 않고 적었던 관찰 정보는 무엇이었나요?",
      "answerTip": "업무를 소개하기보다 실제로 적었던 표현을 예로 들어 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "환자 상태 관찰 기록에 남긴 정보를 활력징후 수치나 통증 척도 등의 구체적인 예로 설명하고, 관찰 시각이나 이전 값처럼 변화가 드러나는 기록 내용을 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "환자 상태 관찰 기록에 활력징후나 통증 정도를 적었다고 설명하지만, 실제 기록 형태나 변화 비교에 필요한 내용은 구체적으로 제시하지 못한다."
          ]
        },
        "poor": {
          "criteria": [
            "환자 상태 관찰 기록에 남긴 정보를 제시하지 않거나, 기록의 중요성이나 인수인계 경험만 이야기한다."
          ]
        }
      }
    }
  ]
}

